// Game data generated by tools/build_game_data (never edit assets/data by hand).
import countriesJson from '../../assets/data/countries.json';
import statesJson from '../../assets/data/us_states.json';
import type { Item, Scene, Tier } from '../logic/types';
import type { Topic } from '../config/levels';

export const COUNTRIES: Item[] = (countriesJson as unknown as { items: Item[] }).items;
export const STATES: Item[] = (statesJson as unknown as { items: Item[] }).items;

export const COUNTRY_BY_ID: Record<string, Item> = Object.fromEntries(COUNTRIES.map((c) => [c.id, c]));
export const STATE_BY_ID: Record<string, Item> = Object.fromEntries(STATES.map((s) => [s.id, s]));

export function itemById(id: string): Item {
  return COUNTRY_BY_ID[id] ?? STATE_BY_ID[id];
}

export function sceneOf(id: string): Scene {
  return id.startsWith('US-') ? 'usa' : 'world';
}

export function itemName(id: string, lang = 'en'): string {
  const it = itemById(id);
  return it ? it.name[lang] ?? it.name.en : id;
}

const TOPIC_REGIONS: Record<Topic, string[] | null> = {
  world: null,
  europe: ['europe'],
  asia: ['asia'],
  africa: ['africa'],
  americas: ['north_america', 'south_america'],
  oceania: ['oceania'],
  usa: null,
};

/** Quiz pool for a topic. For flag questions the tier is the flag tier. */
export function pool(topic: Topic, flags = false): { id: string; tier: Tier }[] {
  if (topic === 'usa') return STATES.filter((s) => s.quiz && s.tier).map((s) => ({ id: s.id, tier: s.tier as Tier }));
  const regions = TOPIC_REGIONS[topic];
  return COUNTRIES.filter((c) => c.quiz && (!regions || regions.includes(c.region)) && (!flags || c.flag))
    .map((c) => ({ id: c.id, tier: (flags ? c.flagTier : c.tier) as Tier }))
    .filter((c) => !!c.tier);
}

/** Atlas regions shown on the Atlas screen. */
export const ATLAS_REGIONS: { id: string; kind: 'country' | 'flag' | 'state'; topic: Topic }[] = [
  { id: 'europe', kind: 'country', topic: 'europe' },
  { id: 'asia', kind: 'country', topic: 'asia' },
  { id: 'africa', kind: 'country', topic: 'africa' },
  { id: 'americas', kind: 'country', topic: 'americas' },
  { id: 'oceania', kind: 'country', topic: 'oceania' },
  { id: 'usa', kind: 'state', topic: 'usa' },
  { id: 'flags', kind: 'flag', topic: 'world' },
];
